mapper.update:
UPDATE biz_notification_outbox
SET status = 'SENDING',
    update_time = #{now}
WHERE id = #{id}
  AND status = 'PENDING'

UPDATE biz_notification_outbox
SET status = 'SENT',
    message_id = #{messageId},
    last_error = NULL,
    update_time = #{now}
WHERE id = #{id}

UPDATE biz_notification_outbox
SET status = 'PENDING',
    update_time = #{now}
WHERE status = 'SENDING'
  AND update_time < #{threshold}

mapper.select:
SELECT COUNT(*)
FROM biz_notification_outbox
WHERE status = #{status}

mapper.delete:
DELETE FROM biz_notification_outbox
WHERE status = 'SENT'
  AND update_time < #{threshold}
